create extension if not exists "pgcrypto";
create type public.user_role as enum ('SUPER_ADMIN','HR_MANAGER','MANAGER','EMPLOYEE');
create type public.attendance_status as enum ('PRESENT','LATE','ABSENT','EARLY_DEPARTURE','OVERTIME');
create type public.leave_status as enum ('PENDING_MANAGER','PENDING_HR','APPROVED','REJECTED','CANCELLED');
create table public.users(id uuid primary key references auth.users(id) on delete cascade,role user_role not null default 'EMPLOYEE',full_name text not null,avatar_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.departments(id uuid primary key default gen_random_uuid(),name text not null unique,description text,manager_id uuid,created_at timestamptz not null default now(),deleted_at timestamptz);
create table public.employees(id uuid primary key default gen_random_uuid(),employee_id text not null unique,user_id uuid unique references public.users(id),department_id uuid references public.departments(id),manager_id uuid references public.employees(id),first_name text not null,last_name text not null,email text not null unique,phone text,address text,emergency_contact jsonb not null default '{}',position text not null,employment_type text not null check(employment_type in ('FULL_TIME','PART_TIME','CONTRACT','INTERN')),employment_date date not null,status text not null default 'ACTIVE',avatar_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),deleted_at timestamptz);
alter table public.departments add constraint departments_manager_fk foreign key(manager_id) references public.employees(id);
create table public.attendance(id uuid primary key default gen_random_uuid(),employee_id uuid not null references public.employees(id),work_date date not null,clock_in timestamptz,clock_out timestamptz,location text,device_id text,status attendance_status not null,metadata jsonb not null default '{}',created_at timestamptz not null default now(),unique(employee_id,work_date));
create table public.shifts(id uuid primary key default gen_random_uuid(),name text not null,start_time time not null,end_time time not null,color text default '#12845b',is_rotational boolean default false,created_at timestamptz default now(),deleted_at timestamptz);
create table public.employee_shifts(id uuid primary key default gen_random_uuid(),employee_id uuid not null references public.employees(id),shift_id uuid not null references public.shifts(id),starts_on date not null,ends_on date,created_at timestamptz default now());
create table public.performance_reviews(id uuid primary key default gen_random_uuid(),employee_id uuid not null references public.employees(id),reviewer_id uuid not null references public.employees(id),period_start date not null,period_end date not null,score numeric(3,2) check(score between 0 and 5),comments text,goals jsonb default '[]',status text default 'DRAFT',reviewed_at timestamptz,created_at timestamptz default now());
create table public.leave_requests(id uuid primary key default gen_random_uuid(),employee_id uuid not null references public.employees(id),leave_type text not null,start_date date not null,end_date date not null,reason text,status leave_status not null default 'PENDING_MANAGER',manager_approved_by uuid references public.employees(id),hr_approved_by uuid references public.employees(id),created_at timestamptz default now(),updated_at timestamptz default now(),check(end_date>=start_date));
create table public.payroll(id uuid primary key default gen_random_uuid(),employee_id uuid not null references public.employees(id),period date not null,basic_salary numeric(14,2) not null,allowances numeric(14,2) default 0,deductions numeric(14,2) default 0,bonuses numeric(14,2) default 0,overtime numeric(14,2) default 0,status text default 'DRAFT',payslip_path text,created_at timestamptz default now(),unique(employee_id,period));
create table public.documents(id uuid primary key default gen_random_uuid(),employee_id uuid references public.employees(id),name text not null,storage_path text not null,mime_type text,created_at timestamptz default now(),deleted_at timestamptz);
create table public.assets(id uuid primary key default gen_random_uuid(),name text not null,category text not null,serial_number text unique,assigned_employee_id uuid references public.employees(id),status text default 'AVAILABLE',maintenance_history jsonb default '[]',created_at timestamptz default now(),updated_at timestamptz default now(),deleted_at timestamptz);
create table public.announcements(id uuid primary key default gen_random_uuid(),title text not null,body text not null,category text default 'GENERAL',published_by uuid references public.users(id),published_at timestamptz,created_at timestamptz default now(),deleted_at timestamptz);
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.users(id),title text not null,body text not null,type text not null,read_at timestamptz,created_at timestamptz default now());
create table public.audit_logs(id bigint generated always as identity primary key,user_id uuid references public.users(id),action text not null,entity_type text not null,entity_id text,old_data jsonb,new_data jsonb,ip inet,created_at timestamptz default now());
create index employees_department_idx on public.employees(department_id) where deleted_at is null;create index attendance_date_idx on public.attendance(work_date desc,employee_id);create index leave_status_idx on public.leave_requests(status,start_date);create index notifications_user_idx on public.notifications(user_id,created_at desc);
create or replace function public.current_role() returns user_role language sql stable security definer set search_path=public as $$select role from public.users where id=auth.uid()$$;
alter table public.users enable row level security;alter table public.departments enable row level security;alter table public.employees enable row level security;alter table public.attendance enable row level security;alter table public.shifts enable row level security;alter table public.employee_shifts enable row level security;alter table public.performance_reviews enable row level security;alter table public.leave_requests enable row level security;alter table public.payroll enable row level security;alter table public.documents enable row level security;alter table public.assets enable row level security;alter table public.announcements enable row level security;alter table public.notifications enable row level security;alter table public.audit_logs enable row level security;
create policy "own user or admins" on public.users for select using(id=auth.uid() or public.current_role() in ('SUPER_ADMIN','HR_MANAGER'));
create policy "authenticated read departments" on public.departments for select to authenticated using(deleted_at is null);
create policy "visible employees" on public.employees for select to authenticated using(deleted_at is null and (user_id=auth.uid() or public.current_role() in ('SUPER_ADMIN','HR_MANAGER','MANAGER')));
create policy "hr manages employees" on public.employees for all to authenticated using(public.current_role() in ('SUPER_ADMIN','HR_MANAGER')) with check(public.current_role() in ('SUPER_ADMIN','HR_MANAGER'));
create policy "visible attendance" on public.attendance for select to authenticated using(employee_id in(select id from employees where user_id=auth.uid()) or public.current_role() in ('SUPER_ADMIN','HR_MANAGER','MANAGER'));
create policy "hr manages attendance" on public.attendance for all to authenticated using(public.current_role() in ('SUPER_ADMIN','HR_MANAGER')) with check(public.current_role() in ('SUPER_ADMIN','HR_MANAGER'));
create policy "visible leave" on public.leave_requests for select to authenticated using(employee_id in(select id from employees where user_id=auth.uid()) or public.current_role() in ('SUPER_ADMIN','HR_MANAGER','MANAGER'));
create policy "employee creates leave" on public.leave_requests for insert to authenticated with check(employee_id in(select id from employees where user_id=auth.uid()));
create policy "managers update leave" on public.leave_requests for update to authenticated using(public.current_role() in ('SUPER_ADMIN','HR_MANAGER','MANAGER'));
create policy "own payroll or hr" on public.payroll for select to authenticated using(employee_id in(select id from employees where user_id=auth.uid()) or public.current_role() in ('SUPER_ADMIN','HR_MANAGER'));
create policy "own notifications" on public.notifications for select to authenticated using(user_id=auth.uid());
create policy "published announcements" on public.announcements for select to authenticated using(published_at is not null and deleted_at is null);
alter publication supabase_realtime add table public.attendance,public.notifications,public.announcements;
